'use strict';
// GENERATED BY session-reader-split script — do not edit manually.
// Behavior-preserving extraction from session-reader.js.

const path = require('node:path');
const fs = require('fs-extra');
const {
  decorateMessagesWithTurnModels,
  normalizeModelReference
} = require('./session-message-metadata');
const {
  getOpenCodeDbPath,
  openOpenCodeDbAtPath
} = require('./opencode-session-store');
const {
  detectOpenCodeDbLayouts,
  detectOpenCodeSessionLayouts
} = require('./opencode-db-layouts');
const { getRealHome, normalizeProjectPathForLookup, getSqliteTableColumns, OPENCODE_TOOL_OUTPUT_MAX_CHARS } = require('./session-reader-utils');

function parseJsonSafe(value) {
  try {
    const parsed = JSON.parse(String(value || ''));
    return parsed && typeof parsed === 'object' ? parsed : null;
  } catch (_error) {
    return null;
  }
}


function isPathWithinRoot(rootPath, candidatePath) {
  const relative = path.relative(rootPath, candidatePath);
  return relative === ''
    || (!relative.startsWith(`..${path.sep}`) && relative !== '..' && !path.isAbsolute(relative));
}


function resolveOpenCodeAuthorizedDbCandidate(candidate, dataRoot) {
  let realDataRoot;
  let realAllowedRoot;
  let realCandidate;
  try {
    realDataRoot = fs.realpathSync(dataRoot);
    realAllowedRoot = fs.realpathSync(candidate.allowedRoot);
    realCandidate = fs.realpathSync(candidate.path);
  } catch (error) {
    if (error && error.code === 'ENOENT') return null;
    throw error;
  }
  if (
    !isPathWithinRoot(realDataRoot, realAllowedRoot)
    || !isPathWithinRoot(realAllowedRoot, realCandidate)
  ) {
    return null;
  }
  try {
    return fs.statSync(realCandidate).isFile()
      ? { path: candidate.path, realPath: realCandidate }
      : null;
  } catch (error) {
    if (error && error.code === 'ENOENT') return null;
    throw error;
  }
}

function collectOpenCodeDbPaths(hostHome) {
  const dbPath = getOpenCodeDbPath(hostHome);
  if (!dbPath) return [];
  const dataRoot = path.dirname(dbPath);
  const candidates = [
    { path: dbPath, allowedRoot: dataRoot }
  ];
  const seen = new Set();
  const dbPaths = [];
  for (const candidate of candidates) {
    const authorized = resolveOpenCodeAuthorizedDbCandidate(candidate, dataRoot);
    if (!authorized || seen.has(authorized.realPath)) continue;
    seen.add(authorized.realPath);
    dbPaths.push(authorized.path);
  }
  return dbPaths;
}


// 会话面读取：两代可同时存在（升级迁移整表拷贝 + WebUI chat 代理在布局迁移前仍只写旧表），
// 同一 id 取 time_updated 更新的副本；并列时保持先扫入的布局——布局表按新代在前声明，
// 等价于「并列时新代优先」。时间戳只影响跨候选 db 的仲裁与列表排序，不承载其它语义。

function readOpenCodeSessionLocationFromDb(dbPath, sessionId) {
  let db = null;
  try {
    db = openOpenCodeDbAtPath(dbPath, { readOnly: true });
    db.exec('PRAGMA query_only = ON;');
    let updatedAt = null;
    for (const layout of detectOpenCodeSessionLayouts(db)) {
      const columns = getSqliteTableColumns(db, layout.sessionTable);
      if (!columns.has('id')) continue;
      const updatedExpr = columns.has('time_updated')
        ? 'time_updated'
        : (columns.has('time_created') ? 'time_created' : '0');
      const row = db.prepare(`
        SELECT id, ${updatedExpr} AS updated_at
        FROM ${layout.sessionTable}
        WHERE id = ?
        LIMIT 1
      `).get(sessionId);
      if (!row || !String(row.id || '').trim()) continue;
      const candidateUpdatedAt = Number(row.updated_at) || 0;
      if (updatedAt === null || candidateUpdatedAt > updatedAt) updatedAt = candidateUpdatedAt;
    }
    if (updatedAt === null) return null;
    return { dbPath, updatedAt };
  } catch (_error) {
    return null;
  } finally {
    if (db && typeof db.close === 'function') {
      try { db.close(); } catch (_closeError) {}
    }
  }
}


function resolveOpenCodeSessionDbPath(sessionId, hostHome = getRealHome()) {
  const id = String(sessionId || '').trim();
  if (!id) return '';
  let selected = null;
  for (const dbPath of collectOpenCodeDbPaths(hostHome)) {
    const candidate = readOpenCodeSessionLocationFromDb(dbPath, id);
    if (!candidate) continue;
    // 跨候选 db 按 updatedAt 选择最新记录；collectOpenCodeDbPaths 以
    // canonical DB 为首，时间相同或缺失时保持 canonical 优先。
    if (!selected || candidate.updatedAt > selected.updatedAt) selected = candidate;
  }
  return selected ? selected.dbPath : '';
}


function readOpenCodeSessionRowsFromDb(dbPath) {
  let db = null;
  try {
    db = openOpenCodeDbAtPath(dbPath, { readOnly: true });
    db.exec('PRAGMA query_only = ON;');
    const byId = new Map();
    for (const layout of detectOpenCodeSessionLayouts(db)) {
      const columns = getSqliteTableColumns(db, layout.sessionTable);
      if (!columns.has('id') || !columns.has('directory') || !columns.has('title')) continue;
      const updatedExpr = columns.has('time_updated') ? 'time_updated' : 'time_created';
      const archivedExpr = columns.has('time_archived') ? 'time_archived' : 'NULL';
      const parentExpr = columns.has('parent_id') ? 'parent_id' : 'NULL';
      const rows = db.prepare(`
        SELECT id, directory, title, ${updatedExpr} AS updated_at,
               ${archivedExpr} AS time_archived, ${parentExpr} AS parent_id
        FROM ${layout.sessionTable}
        WHERE id <> ''
      `).all();
      for (const row of rows) {
        const id = String(row && row.id || '').trim();
        if (!id) continue;
        const updatedAt = Number(row && row.updated_at) || 0;
        const existing = byId.get(id);
        // 同一 id 两代都有时取更新更晚的副本；并列保持先扫入的布局（新代优先）。
        if (existing && existing.updatedAt >= updatedAt) continue;
        byId.set(id, {
          id,
          directory: row.directory,
          title: row.title,
          updatedAt,
          timeArchived: row.time_archived,
          parentId: row.parent_id
        });
      }
    }
    // 归档与子会话过滤放在跨布局合并之后：新代把会话标成已归档/子代理会话时，旧代冻结的
    // NULL 副本不能把它重新捞回列表。parent_id 非空 = opencode 的子代理(Task/并行 review
    // 子会话，title 带 "(@... subagent)")，属于父会话本轮执行的一部分，不该当独立顶层会话
    // 列进会话列表（否则一次并行 review 会衍生出一堆碎片会话，体验很差）。
    return Array.from(byId.values())
      .filter((row) => (
        row.timeArchived == null
        && (row.parentId == null || String(row.parentId) === '')
      ))
      .sort((a, b) => (
        (b.updatedAt - a.updatedAt)
        || (a.id < b.id ? 1 : (a.id > b.id ? -1 : 0))
      ))
      .map((row) => ({
        id: row.id,
        directory: row.directory,
        title: row.title,
        updated_at: row.updatedAt
      }));
  } catch (_error) {
    return [];
  } finally {
    if (db && typeof db.close === 'function') {
      try { db.close(); } catch (_closeError) {}
    }
  }
}


function readOpenCodeProjectsFromHostByPaths(projectPaths = []) {
  const hostHome = getRealHome();
  const targetPaths = new Set(
    (Array.isArray(projectPaths) ? projectPaths : [])
      .map((projectPath) => normalizeProjectPathForLookup(projectPath))
      .filter(Boolean)
  );
  const hasProjectFilter = targetPaths.size > 0;

  // 跨所有候选 db 收集会话，按 id 去重（同 id 保留 updatedAt 更新的一条）。
  const sessionById = new Map();
  for (const dbPath of collectOpenCodeDbPaths(hostHome)) {
    for (const row of readOpenCodeSessionRowsFromDb(dbPath)) {
      const id = String(row && row.id || '').trim();
      const directory = normalizeProjectPathForLookup(row && row.directory);
      const title = String(row && row.title || '').trim();
      if (!id || !directory) continue;
      if (hasProjectFilter && !targetPaths.has(directory)) continue;
      const updatedAt = Number(row && row.updated_at) || 0;
      const existing = sessionById.get(id);
      if (existing && existing.updatedAt >= updatedAt) continue;
      sessionById.set(id, { id, directory, title: title || id, updatedAt, provider: 'opencode' });
    }
  }

  const byProjectPath = new Map();
  for (const session of sessionById.values()) {
    if (!byProjectPath.has(session.directory)) byProjectPath.set(session.directory, []);
    byProjectPath.get(session.directory).push({
      id: session.id,
      title: session.title,
      updatedAt: session.updatedAt,
      provider: 'opencode'
    });
  }
  return Array.from(byProjectPath.entries()).map(([projectPath, sessions]) => ({
    id: 'opencode-' + Buffer.from(projectPath).toString('base64').replace(/[/+=]/g, '_'),
    name: path.basename(projectPath) || projectPath,
    path: projectPath,
    sessions: sessions.sort((a, b) => b.updatedAt - a.updatedAt),
    provider: 'opencode'
  }));
}


function readOpenCodeProjectsFromHost() {
  return readOpenCodeProjectsFromHostByPaths([]);
}

// 账号隔离存储的路径/数据库格式仍由各 Provider adapter 负责；这里只按合同
// 声明的 accountSessionStore 能力分派，不把 Provider 名单复制到通用入口。

function normalizeOpenCodeMessageText(text, role) {
  let out = String(text || '').trim();
  if (role === 'user') out = out.replace(/^User:\s*/i, '').trim();
  if (role === 'assistant') out = out.replace(/^Assistant:\s*/i, '').trim();
  return out;
}

// 子会话（Task 子代理）的最终 assistant 文本：父会话的 task tool part 被中断时 output 为空，
// 但子代理往往已在自己的会话里产出了完整结果——回读它,让父会话能看到子代理干了什么。
// 子会话可能只存在于任一代（迁移后新建的子会话只在新代表里），因此两代都要找，
// 候选统一按消息时间取最新（同一消息内与旧代「最新 part」口径一致，取最后一个非空 text 条目）。

function readOpenCodeChildFinalText(db, childSessionId) {
  const childId = String(childSessionId || '').trim();
  if (!childId) return '';
  try {
    const candidates = [];
    for (const layout of detectOpenCodeDbLayouts(db)) {
      if (layout.contentModel === 'inline') {
        const typeExpr = layout.messageTypeColumn ? layout.messageTypeColumn : 'NULL';
        const rows = db.prepare(`
          SELECT ${typeExpr} AS message_type, time_created, data
          FROM ${layout.messageTable}
          WHERE session_id = ?
          ORDER BY time_created DESC, id DESC
        `).all(childId);
        for (const row of rows) {
          const type = String(row && row.message_type || '').trim().toLowerCase();
          if (type !== 'assistant') continue;
          const data = parseJsonSafe(row && row.data);
          const items = Array.isArray(data && data.content) ? data.content : [];
          for (let index = items.length - 1; index >= 0; index -= 1) {
            const item = items[index];
            const text = item && item.type === 'text' ? String(item.text || '').trim() : '';
            if (!text) continue;
            candidates.push({ timeCreated: Number(row && row.time_created) || 0, text });
            break;
          }
        }
      } else if (layout.partTable) {
        const rows = db.prepare(`
          SELECT
            ${layout.messageTable}.data AS message_data,
            ${layout.messageTable}.time_created AS message_time_created,
            ${layout.partTable}.data AS part_data
          FROM ${layout.partTable}
          JOIN ${layout.messageTable} ON ${layout.partTable}.message_id = ${layout.messageTable}.id
          WHERE ${layout.messageTable}.session_id = ?
          ORDER BY ${layout.messageTable}.time_created DESC, ${layout.partTable}.time_created DESC
        `).all(childId);
        for (const row of rows) {
          const msg = parseJsonSafe(row && row.message_data);
          if (!msg || msg.role !== 'assistant') continue;
          const part = parseJsonSafe(row && row.part_data);
          if (part && part.type === 'text' && String(part.text || '').trim()) {
            candidates.push({
              timeCreated: Number(row && row.message_time_created) || 0,
              text: String(part.text).trim()
            });
          }
        }
      }
    }
    candidates.sort((a, b) => b.timeCreated - a.timeCreated);
    return candidates.length ? candidates[0].text : '';
  } catch (_error) { /* 子会话读不到不阻塞父会话渲染 */ }
  return '';
}

// 子代理的回复常按 opencode 的任务模板包在 <task>/<task_result> 里，透传到 webUI 会显示成
// 一对孤零零的未闭合标签（</task_result></task> 裸露在文本尾部）。渲染前剥掉这层包装。

function stripTaskWrapperTags(text) {
  return String(text || '')
    .replace(/<\/?task(?:_result)?>/gi, '')
    .trim();
}

// 安全上限：子代理报告/工具输出可能很长，给个宽松的兜底避免极端条目撑爆 messages 载荷。

function capOpenCodeToolText(text) {
  const value = String(text || '');
  if (value.length <= OPENCODE_TOOL_OUTPUT_MAX_CHARS) return value;
  return `${value.slice(0, OPENCODE_TOOL_OUTPUT_MAX_CHARS)}\n…(截断,共 ${value.length} 字符)`;
}

// opencode 历史 tool part → 与实时流一致的 :::tool / :::tool-result 标签（claude/codex 历史早已
// 这样渲染，opencode 此前把 tool part 全丢了 → 工具调用/子代理在历史里完全不可见,会话看着
// "没处理完"）。task 工具额外处理：output 为空（run 被中断）时回读子会话的最终产出。

function renderOpenCodeToolPart(db, part) {
  const toolName = String(part && part.tool || 'Tool').replace(/["\\\r\n]/g, '').trim() || 'Tool';
  const state = part && part.state && typeof part.state === 'object' ? part.state : {};
  let body = '';
  try {
    body = state.input == null ? '' : JSON.stringify(state.input, null, 2);
  } catch (_error) {
    body = String(state.input || '');
  }
  let result = String(state.output || '').trim();
  if (!result) {
    // 新代 tool 条目的产出放在 state.content 的文本条目数组里（旧代是 state.output 字符串；
    // 迁移只对单文本条目做一对一拷贝，多条目按行拼接兜底）。
    const contentItems = Array.isArray(state.content) ? state.content : [];
    result = contentItems
      .map((item) => (item && item.type === 'text' ? String(item.text || '') : ''))
      .filter(Boolean)
      .join('\n')
      .trim();
  }
  if (toolName === 'task') {
    result = stripTaskWrapperTags(result);
    const metadata = state.metadata && typeof state.metadata === 'object' ? state.metadata : {};
    const childId = String(metadata.sessionId || metadata.sessionID || '').trim();
    if (!result && childId) {
      const childText = stripTaskWrapperTags(readOpenCodeChildFinalText(db, childId));
      if (childText) {
        result = `[子代理会话 ${childId} 的产出]\n\n${childText}`;
      } else {
        result = `(子代理会话 ${childId} 无产出——任务被中断或仍在运行)`;
      }
    }
  }
  let rendered = `\n:::tool{name="${toolName}"}\n${capOpenCodeToolText(body).trim()}\n:::\n`;
  if (result) rendered += `\n:::tool-result\n${capOpenCodeToolText(result)}\n:::\n`;
  return rendered;
}


// 旧代（contentModel='parts'）消息渲染：角色在 message.data.role，内容在独立 part 表。

function readOpenCodePartBasedMessages(db, layout, sessionId) {
  const rows = db.prepare(`
    SELECT
      ${layout.messageTable}.id AS message_id,
      ${layout.messageTable}.time_created AS message_time_created,
      ${layout.messageTable}.data AS message_data,
      ${layout.partTable}.time_created AS part_time_created,
      ${layout.partTable}.data AS part_data
    FROM ${layout.messageTable}
    LEFT JOIN ${layout.partTable} ON ${layout.partTable}.message_id = ${layout.messageTable}.id
    WHERE ${layout.messageTable}.session_id = ?
    ORDER BY ${layout.messageTable}.time_created ASC, ${layout.messageTable}.id ASC, ${layout.partTable}.time_created ASC, ${layout.partTable}.id ASC
  `).all(sessionId);
  const byMessage = new Map();
  for (const row of rows) {
    const messageId = String(row && row.message_id || '').trim();
    if (!messageId) continue;
    if (!byMessage.has(messageId)) {
      byMessage.set(messageId, {
        messageId,
        data: parseJsonSafe(row && row.message_data),
        timeCreated: Number(row && row.message_time_created) || 0,
        parts: []
      });
    }
    const partData = parseJsonSafe(row && row.part_data);
    if (partData) byMessage.get(messageId).parts.push(partData);
  }
  const messages = [];
  for (const message of byMessage.values()) {
    const role = String(message && message.data && message.data.role || '').trim();
    if (role !== 'user' && role !== 'assistant') continue;
    const content = message.parts
      .map((part) => {
        if (!part || typeof part !== 'object') return '';
        if (part.type === 'text') return String(part.text || '');
        if (part.type === 'reasoning') return `\n:::thinking\n${String(part.text || '').trim()}\n:::\n`;
        if (part.type === 'tool') return renderOpenCodeToolPart(db, part);
        return '';
      })
      .filter(Boolean)
      .join('\n')
      .trim();
    const normalizedContent = normalizeOpenCodeMessageText(content, role);
    if (!normalizedContent) continue;
    const messageModel = normalizeModelReference(message.data.model || message.data);
    messages.push({
      messageId: message.messageId,
      role,
      content: normalizedContent,
      timeCreated: message.timeCreated,
      ...(messageModel ? { model: messageModel } : {})
    });
  }
  return messages;
}

// 新代（contentModel='inline'）消息渲染：角色在 message 行的 type 列（data 里没有 role），
// 内容内嵌在 data.content 数组（text/reasoning/tool 条目）。user/synthetic 的正文直接在
// data.text——自动续写/系统注入在迁移前的旧代里就是 role=user 的 text part，展示口径保持一致；
// compaction/system/idle/agent-switched 等是运行时标记（自动压缩摘要、工具变更通告），
// 迁移前同样不进历史时间线，这里也不渲染。

function readOpenCodeInlineMessages(db, layout, sessionId) {
  const typeExpr = layout.messageTypeColumn ? layout.messageTypeColumn : 'NULL';
  const rows = db.prepare(`
    SELECT id AS message_id, ${typeExpr} AS message_type, time_created, data
    FROM ${layout.messageTable}
    WHERE session_id = ?
    ORDER BY time_created ASC, id ASC
  `).all(sessionId);
  const messages = [];
  for (const row of rows) {
    const messageId = String(row && row.message_id || '').trim();
    if (!messageId) continue;
    const data = parseJsonSafe(row && row.data);
    if (!data) continue;
    // 角色判定：行带 message_type（新代 type 列）时以它为准，否则回退 data.role
    // （与用量扫描器同一口径，避免同一行一处算用户内容、一处不算）。
    const type = String(row.message_type || data.role || '').trim().toLowerCase();
    const role = type === 'assistant'
      ? 'assistant'
      : ((type === 'user' || type === 'synthetic') ? 'user' : '');
    if (!role) continue;
    let content = '';
    if (role === 'assistant') {
      const items = Array.isArray(data.content) ? data.content : [];
      content = items
        .map((item) => {
          if (!item || typeof item !== 'object') return '';
          if (item.type === 'text') return String(item.text || '');
          if (item.type === 'reasoning') return `\n:::thinking\n${String(item.text || '').trim()}\n:::\n`;
          if (item.type === 'tool') {
            // 新代 tool 条目的工具名在 name 字段、state 结构与旧代 part.state 相同，
            // 规范化成旧代 part 形状后与旧代共用同一个渲染器（含 task 子会话产出回读）。
            return renderOpenCodeToolPart(db, { tool: item.name || item.tool, state: item.state });
          }
          return '';
        })
        .filter(Boolean)
        .join('\n')
        .trim();
    } else {
      content = String(data.text || '');
    }
    const normalizedContent = normalizeOpenCodeMessageText(content, role);
    if (!normalizedContent) continue;
    const messageModel = normalizeModelReference(data.model || data);
    messages.push({
      messageId,
      role,
      content: normalizedContent,
      timeCreated: Number(row && row.time_created) || 0,
      ...(messageModel ? { model: messageModel } : {})
    });
  }
  return messages;
}

function readOpenCodeMessagesFromDb(dbPath, id, options = {}) {
  let db = null;
  try {
    db = openOpenCodeDbAtPath(dbPath, { readOnly: true });
    db.exec('PRAGMA query_only = ON;');
    // 两代可同时存在且两侧都有独有行（旧表迁移只在升级时跑一次，之后写进旧表的行不会进新表）
    // → 扫全部存在的布局、按消息 id 合并；同一 id 两侧都可渲染时保持先扫入的布局
    // （布局表按新代在前声明），某一侧渲染为空（运行时标记/空内容）时不遮挡另一侧的可渲染副本。
    const byMessage = new Map();
    for (const layout of detectOpenCodeDbLayouts(db)) {
      const entries = layout.contentModel === 'inline'
        ? readOpenCodeInlineMessages(db, layout, id)
        : (layout.partTable ? readOpenCodePartBasedMessages(db, layout, id) : []);
      for (const entry of entries) {
        if (!byMessage.has(entry.messageId)) byMessage.set(entry.messageId, entry);
      }
    }
    return Array.from(byMessage.values())
      .sort((a, b) => (
        (a.timeCreated - b.timeCreated)
        || (a.messageId < b.messageId ? -1 : (a.messageId > b.messageId ? 1 : 0))
      ))
      .map((message) => ({
        role: message.role,
        content: message.content,
        timestamp: new Date(message.timeCreated || Date.now()).toISOString(),
        ...(message.model ? { model: message.model } : {})
      }));
  } catch (error) {
    if (options.throwOnError) throw error;
    return [];
  } finally {
    if (db && typeof db.close === 'function') {
      try { db.close(); } catch (_closeError) {}
    }
  }
}

// 会话可能同时存在于 canonical 与 recovery DB；统一选择更新时间最新的
// session 记录，避免列表、消息、模型各自命中不同副本。

function readOpenCodeSessionMessages(sessionId, options = {}) {
  const id = String(sessionId || '').trim();
  if (!id) return [];
  const dbPath = resolveOpenCodeSessionDbPath(id);
  return dbPath ? readOpenCodeMessagesFromDb(dbPath, id, options) : [];
}

// opencode 会话的当前模型：真相在 opencode DB 的 session 表 model 列
// （形如 {"id":"glm-5.2","providerID":"opencode-go",...} → "opencode-go/glm-5.2"），
// 而非 model_usage_records（那条对 opencode 会返回错的/上一次代理用模）。用于刷新后正确召回
// "会话上次使用的模型"。跨所有候选 db 找该会话；两代都有时按布局表顺序取（新代是活跃值，
